import { Checkbox } from "@/registry/erbium/ui/checkbox";
import { useDragSelect } from "@/registry/erbium/hooks/use-drag-select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/registry/erbium/ui/table";
import {
  createColumnHelper,
  metaHelper,
  rowSelectionFeature,
  tableFeatures,
  useTable,
} from "@tanstack/react-table";

interface User {
  id: string;
  name: string;
  email: string;
  role: string;
}

const tableData: User[] = [
  { email: "sarah.chen@example.com", id: "1", name: "Sarah Chen", role: "Admin" },
  { email: "marcus.rodriguez@example.com", id: "2", name: "Marcus Rodriguez", role: "User" },
  { email: "priya.patel@example.com", id: "3", name: "Priya Patel", role: "User" },
  { email: "david.kim@example.com", id: "4", name: "David Kim", role: "Editor" },
];

const features = tableFeatures({
  columnMeta: metaHelper<{ selection?: boolean }>(),
  rowSelectionFeature,
});

const columnHelper = createColumnHelper<typeof features, User>();

const columns = columnHelper.columns([
  columnHelper.display({
    cell: ({ row }) => (
      <Checkbox
        aria-label={`Select ${row.original.name}`}
        checked={row.getIsSelected()}
        disabled={!row.getCanSelect()}
        onCheckedChange={(checked) => {
          row.toggleSelected(checked);
        }}
      />
    ),
    header: ({ table }) => (
      <Checkbox
        aria-label="Select all rows"
        checked={table.getIsAllRowsSelected()}
        // v9's getIsSomeRowsSelected() is also true when every row is selected.
        indeterminate={table.getIsSomeRowsSelected() && !table.getIsAllRowsSelected()}
        onCheckedChange={(checked) => {
          table.toggleAllRowsSelected(checked);
        }}
      />
    ),
    id: "select",
    meta: { selection: true },
  }),
  columnHelper.accessor("name", {
    cell: (info) => <span className="font-medium">{info.getValue()}</span>,
    header: "Name",
  }),
  columnHelper.accessor("email", { header: "Email" }),
  columnHelper.accessor("role", { header: "Role" }),
]);

export default function CheckboxInTableExample() {
  const table = useTable({
    columns,
    data: tableData,
    features,
    getRowId: (row) => row.id,
    initialState: { rowSelection: { "1": true } },
  });

  const { rows } = table.getRowModel();

  const dragSelect = useDragSelect({
    resolve(target) {
      const index = target.closest("tr")?.sectionRowIndex ?? -1;
      const row = rows[index];

      return row?.getCanSelect() ? { index, selected: row.getIsSelected() } : null;
    },
    selectRange(start, end, selected) {
      for (const row of rows.slice(start, end + 1)) {
        if (row.getCanSelect()) {
          row.toggleSelected(selected);
        }
      }
    },
  });

  return (
    <Table>
      <TableHeader>
        {table.getHeaderGroups().map((headerGroup) => (
          <TableRow key={headerGroup.id}>
            {headerGroup.headers.map((header) => (
              <TableHead
                className={header.column.columnDef.meta?.selection === true ? "w-8" : undefined}
                key={header.id}
              >
                {header.isPlaceholder ? null : <table.FlexRender header={header} />}
              </TableHead>
            ))}
          </TableRow>
        ))}
      </TableHeader>
      <TableBody {...dragSelect}>
        {rows.map((row) => (
          <TableRow data-state={row.getIsSelected() ? "selected" : undefined} key={row.id}>
            {row.getAllCells().map((cell) => (
              <TableCell
                className={cell.column.columnDef.meta?.selection === true ? "w-8" : undefined}
                key={cell.id}
              >
                <table.FlexRender cell={cell} />
              </TableCell>
            ))}
          </TableRow>
        ))}
      </TableBody>
    </Table>
  );
}

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

/**
 * The box an example renders in. Inline it is capped to the reading width; with `fill` (a
 * full-screen slide) it takes the whole panel, so an example sized from its container (`w-full`,
 * `h-full` with a minimum) grows with it, while one with a natural size stays centred.
 */
export const ShowcaseSurface = ({
  children,
  fill = false,
}: {
  children?: ReactNode;
  fill?: boolean;
}) => (
  <div
    data-slot="component-preview"
    className={cn(
      "relative isolate mx-auto flex w-full min-w-0 items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center",
      fill ? "flex-1" : "min-h-64 max-w-3xl",
    )}
  >
    {children}
  </div>
);

import { cn } from "@/registry/erbium/lib/erbium-utils";
import { Icon } from "@/registry/erbium/ui/icon";

import { Button } from "@/registry/erbium/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
  DropdownMenuList,
} from "@/registry/erbium/ui/dropdown-menu";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/registry/erbium/ui/table";
import { createColumnHelper, metaHelper, tableFeatures, useTable } from "@tanstack/react-table";

interface Product {
  id: string;
  name: string;
  price: number;
}

const products: Product[] = [
  { id: "mouse", name: "Wireless Mouse", price: 29.99 },
  { id: "keyboard", name: "Mechanical Keyboard", price: 129.99 },
  { id: "hub", name: "USB-C Hub", price: 49.99 },
];

const currency = new Intl.NumberFormat("en-US", { currency: "USD", style: "currency" });

const features = tableFeatures({
  columnMeta: metaHelper<{ alignment?: "end"; narrow?: boolean }>(),
});

const columnHelper = createColumnHelper<typeof features, Product>();

const columns = columnHelper.columns([
  columnHelper.accessor("name", {
    cell: (info) => <span className="font-medium">{info.getValue()}</span>,
    header: "Product",
  }),
  columnHelper.accessor("price", {
    cell: (info) => currency.format(info.getValue()),
    header: "Price",
  }),
  // Display columns have no accessor; they render UI for each row.
  columnHelper.display({
    cell: ({ row }) => (
      <DropdownMenu>
        <DropdownMenuTrigger render={<Button variant="ghost" size="icon" />}>
          <Icon name="more-horizontal" />
          <span className="sr-only">Open menu for {row.original.name}</span>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          <DropdownMenuList>
            <DropdownMenuItem>Edit</DropdownMenuItem>
            <DropdownMenuItem>Duplicate</DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem variant="error">Delete</DropdownMenuItem>
          </DropdownMenuList>
        </DropdownMenuContent>
      </DropdownMenu>
    ),
    header: "Actions",
    id: "actions",
    meta: { alignment: "end" },
  }),
]);

export default function TableActionsExample() {
  const table = useTable({ columns, data: products, features, getRowId: (row) => row.id });

  return (
    <Table>
      <TableHeader>
        {table.getHeaderGroups().map((headerGroup) => (
          <TableRow key={headerGroup.id}>
            {headerGroup.headers.map((header) => (
              <TableHead
                className={cn(
                  header.column.columnDef.meta?.alignment === "end" && "text-end tabular-nums",
                  header.column.columnDef.meta?.narrow === true && "w-25",
                )}
                key={header.id}
              >
                {header.isPlaceholder ? null : <table.FlexRender header={header} />}
              </TableHead>
            ))}
          </TableRow>
        ))}
      </TableHeader>
      <TableBody>
        {table.getRowModel().rows.map((row) => (
          <TableRow key={row.id}>
            {row.getAllCells().map((cell) => (
              <TableCell
                className={cn(
                  cell.column.columnDef.meta?.alignment === "end" && "text-end tabular-nums",
                  cell.column.columnDef.meta?.narrow === true && "w-25",
                )}
                key={cell.id}
              >
                <table.FlexRender cell={cell} />
              </TableCell>
            ))}
          </TableRow>
        ))}
      </TableBody>
    </Table>
  );
}

